codeExample.bad:
/* A cookie consent banner partially overlaps the bottom edge of
   focused form fields near the bottom of the viewport, satisfying
   the AA minimum but not the stricter AAA "no part hidden" rule */
.cookie-banner {
  position: fixed;
  bottom: 0;
  height: 60px;
}
input, button {
  scroll-margin-bottom: 20px; /* not enough to clear the banner fully */
}

codeExample.good:
/* scroll-margin-bottom matches the banner's full height, so focused
   elements scroll completely clear of it, satisfying the AAA rule */
.cookie-banner {
  position: fixed;
  bottom: 0;
  height: 60px;
}
input, button {
  scroll-margin-bottom: 70px;
}
